function compute(inputs) {
  const p = Math.min(1, Math.max(0.1, inputs.p));
  const mask = inputs.mask.map(v => v >= 0.5 ? 1 : 0);
  const z = inputs.z;
  const n = z.length;
  const y = z.map((zi, i) => (zi * mask[i]) / p);
  const y_no_rescale = z.map((zi, i) => zi * mask[i]);
  const expected_y = z.map(zi => zi); // E[y] = z when mask ~ Bernoulli(p) and rescale by 1/p
  const table = {
    columns: ["Unit", "z_i", "m_i", "z_i * m_i", "y_i = (z_i * m_i)/p"],
    rows: z.map((zi, i) => [i+1, zi.toFixed(2), mask[i], (zi*mask[i]).toFixed(2), y[i].toFixed(2)])
  };
  const flow = {
    nodes: [
      { id: "input", label: "Input h", value: "" },
      { id: "linear", label: "Linear z = Wh+b", value: z.map(v=>v.toFixed(2)).join(", ") },
      { id: "mask", label: "Mask m", value: mask.join(", ") },
      { id: "drop", label: "Dropout z⊙m", value: z.map((v,i)=>(v*mask[i]).toFixed(2)).join(", ") },
      { id: "rescale", label: "Rescale /p", value: y.map(v=>v.toFixed(2)).join(", ") }
    ],
    edges: [
      { from: "input", to: "linear", label: "W,b", value: "" },
      { from: "linear", to: "drop", label: "", value: "" },
      { from: "mask", to: "drop", label: "", value: "" },
      { from: "drop", to: "rescale", label: "1/p", value: (1/p).toFixed(2) }
    ]
  };
  const sum_y = y.reduce((a,b)=>a+b,0);
  const sum_z = z.reduce((a,b)=>a+b,0);
  const insight = `With p=${p.toFixed(2)}, the rescale factor is ${(1/p).toFixed(2)}. ` +
    `The sum of outputs is ${sum_y.toFixed(2)} (vs. sum of pre-activations ${sum_z.toFixed(2)}). ` +
    `Dropped units (mask=0) contribute 0. ` +
    `Expected output per unit equals z_i when mask is random with keep probability p.`;
  return {
    y: y,
    y_no_rescale: y_no_rescale,
    expected_y: expected_y,
    table: table,
    flow: flow,
    insight: insight
  };
}
